"""Write bounded physical-review reports and exact-schema batch results."""
import csv, json
from pathlib import Path

B=Path(__file__).resolve().parent
Q=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf-8')))
F={x['sample_id']:x for x in json.loads((B/'lead-fold-coverage.json').read_text())}
G={x['sample_id']:x for x in json.loads((B/'lead-gaia-covariance.json').read_text())}
CURRENT={x['sample_id']:x for x in json.loads((B/'lead-current-sectors.json').read_text())}
NEW=json.loads((B/'lead-new-pixels.json').read_text())

I={
'T061':dict(verdict='REFUTED',evidence='Sector 84 QLP SAP contains two extraordinary asymmetric drops near BTJD 3585.8 and 3599.3, separated by about 13.5 d. The screened 3599.55 box samples a ~208 ppt core deficit. At the same Gaia-period phase, s16, s17 and s57 have 1.00, 0.97 and 0.87 time-bin core coverage with ~0, +0.6 and -1.6 ppt local contrast. Those are informative historical non-repeats under the assumed phase. The two s84 troughs are same-sector features and cannot establish same-kind orbital recurrence.',alternative='The independent TESSCut pixel cube has the G=11.3058 target at (5.17,5.94) and a brighter G=10.5737 neighbor 23.72 arcsec away at (6.22,6.34), both at the active edge. Its 11x11 cutout contains 44 zero edge pixels, invalidating a lowest-pixel background estimator. Terra used active-sky pixels instead: background rises about 50.6 and 88.6 counts per pixel at the two QLP troughs, while raw target and neighbor pixels rise too. A target-plus-neighbor 4x3 extraction after valid sky correction shows only 0.042% and 0.408% deficits, versus QLP SAP 15.07% and 24.11% in the same windows. This direct same-photon pixel contradiction and sky correlation positively identify the huge QLP dips as extraction/background artifacts. The small pixel residuals cannot be localized because both PSFs are truncated at the edge.',geometry='Gaia SB1 P=29.01388 d; the 3599.55 screening time is 1.69 d before the nearest edge-on Gaia conjunction with linear covariance allowance 2.82 d. Geometry cannot rescue QLP troughs contradicted by the raw pixels.',limitations='The edge-truncated TESSCut aperture cannot establish whether a much smaller physical signal belongs to either star. The selected 15-24% QLP eclipse interpretation is refuted.',next='Only a target-flux-valid, fully captured aperture or independent photometry showing a repeated isolated deficit would reopen the eclipse claim.'),
'T062':dict(verdict='PLAUSIBLE',evidence='The s24 ~1971.41 window contains an ~7-9 ppt local notch on a strongly sloping raw baseline. Three other retained windows in the same sector have dissimilar irregular shapes; the 1957.45 window intersects a ~14.7 ppt local step and the 1970.39 window is a rising flank. Conditional Gaia-period checks elsewhere sample near-flat flux, but their endpoints, side baselines and accumulated timing error do not establish a comprehensive sensitive null. The 1971 notch might still be a single physical event.',alternative='KSPSAP removes much of the s24 drift and the notch is less distinct. This same-photon alternative favors a trend explanation but does not by itself prove an artifact. No deciding difference pixel is available for the small s24 notch.',geometry='Gaia P=48.99010 d. The 1971.41 screen is 5.00 d from the closest edge-on conjunction versus a 1.77 d linear covariance allowance, so association with that spectroscopic orbit is weak. A different eclipse period is untested.',limitations='The event center, source and repeat period are insecure; the s24 baseline is strongly variable.',next='Test a future clean raw notch and locate it in difference pixels before fitting an eclipse period.'),
'T063':dict(verdict='PLAUSIBLE',evidence='The s64 3067.23 flag is a ~5 ppt local notch embedded in a sector-wide rise and later large brightenings. It lacks a clean stable baseline, but the local depression could be a small single event. Conditional Gaia-period checks in s10 and s63 are flat at their screened phases; they do not rule out other timing aliases or a signal of different depth.',alternative='The notch and sector-wide excursion are suppressed in KSPSAP, an alternative reduction of the same photons. Suppression of a shallow feature is not decisive artifact evidence. No event difference image has established source position.',geometry='The screen is 0.21 d from the nearest Gaia conjunction with 2.21 d linear allowance, compatible but not a measured event center or period.',limitations='Morphology is insecure against the brightening baseline; no repeat or source attribution is established.',next='Obtain a bracketed repeated raw dip and target-centered difference image.'),
'T064':dict(verdict='REFUTED',evidence='The s88 3703.16 flag is a shallow valley in a broad and rapidly changing baseline. Two large s88 brightenings near 3691 and 3706 bracket that sector; a 0.25 d gap near 3704 changes the raw level by ~32 ppt. The newly available s109 target-containing pixels likewise show two enormous brightenings near 4320 and 4333 with slow recovery. The predicted s109 phase 4324.42 lies in a quiet intervening stretch of a target-flux-valid 1x1 and 3x3 extraction.',alternative='The s109 TESSCut target pixel has median ~3072 counts and zero median-valued edge pixels, so its aperture is meaningful. The recurring brightenings/ramps, not an isolated eclipse, explain the screened s88 valley. The s109 extraction uses later photons; the s88 QLP corrected light curve is an alternative reduction of the original photons.',geometry='Gaia P=38.82891 d; s88 screen is 0.17 d from edge-on conjunction within 0.87 d linear allowance, but the flagged shape is not an eclipse.',limitations='The new-sector extraction has no local background correction; its very large positive excursions make the qualitative shape robust, but small-amplitude null depth is not calibrated.',next='Reopen only for an isolated target-centered raw deficit independent of the broad brightenings.'),
'T065':dict(verdict='PLAUSIBLE',evidence='The s96 3925.93 screened trough is ~5 ppt and broad, with a recovery interrupted by a 0.27 d gap and an ~6.6 ppt upward level change. This makes a secure center impossible, but the pre-gap depression might be a single physical event. The full-sector raw traces also show end-of-segment brightenings in s28 and s68. Conditional Gaia-phase samples in s27 and s68 are near zero contrast; they do not establish a period-independent exclusion.',alternative='KSPSAP suppresses the broad drift; it shares the photons and cannot alone refute a possible long eclipse. The gap/step makes an extraction explanation credible but does not prove the entire depression is instrumental.',geometry='The screen is ~7.41 d from nearest Gaia conjunction, within a broad 7.80 d linear uncertainty; neither this loose consistency nor the period fold establishes an eclipse.',limitations='One incompletely bracketed shallow event; center, recurrence and source attribution are unresolved.',next='Obtain a fully bracketed raw repeat and target-centered pixel deficit before fitting a period.'),
'T066':dict(verdict='REFUTED',evidence='The s86 3650.15 flag samples a low branch before a 0.53 d gap and a long post-gap rise; no ingress and return to a stable baseline are present. s53, s58 and s78 Gaia-phase windows are covered and near zero or show dissimilar low-amplitude drift. s73 has a large brightening with slow recovery, showing the same kind of sector-scale behavior.',alternative='KSPSAP attenuates the trends. The discontinuity and long recovery in raw SAP, plus unlike predicted windows, positively favor a baseline/extraction feature over an eclipse.',geometry='The s86 screen is 9.98 d from the nearest Gaia conjunction with 1.71 d linear allowance, strongly inconsistent under this edge-on approximation.',limitations='The gap prevents any precise center for the s86 decline.',next='A separate isolated raw dip would be required to reopen the selected eclipse claim.'),
'T067':dict(verdict='PLAUSIBLE',evidence='The s2 1364.43 flag is a ~1-3 ppt shallow local depression within irregular baseline motion. The same sector later develops much larger brightenings and edge excursions. Conditional Gaia-period phase checks from s7 through s89 look flat near their point predictions, but their accumulated timing uncertainty and local baseline validity make them insufficient to refute a small single event.',alternative='KSPSAP attenuates the s2 fluctuation and later positive excursions. A noise/extraction explanation is credible, yet the raw local depression has no decisive positive artifact signature. The same-photon corrected series does not independently test recurrence.',geometry='The s2 screen is 4.29 d from the nearest Gaia conjunction, about 2.06 linear sigma; its relation to that orbit is uncertain and no eclipse ephemeris is measured.',limitations='Low signal-to-noise single feature; source attribution and recurrence are unresolved.',next='Require a cleaner repeated raw deficit with a measured center and valid source pixels.'),
'T068':dict(verdict='REFUTED',evidence='The s17 retained dip screen at 1788.36 is actually on a sharp raw brightening/ramp: the measured core is about +12 ppt relative to its baseline. The same sector has strong positive end-of-interval ramps. Sixteen other sectors sample approximately flat flux at the Gaia-period point predictions, conditional on that period and their local coverage.',alternative='KSPSAP largely removes the s17 ramp. The sign of the raw event and its asymmetric rising shape positively refute an eclipse interpretation for this flag; the conditional phase checks are secondary context.',geometry='The s17 screen is ~15.83 d from the nearest Gaia conjunction versus 3.09 d linear allowance.',limitations='The raw positive excursion could have a separate source or astrophysical cause; it is not an eclipse.',next='No eclipse follow-up from this flag; inspect any future independent dip on its own merits.'),
'T069':dict(verdict='PLAUSIBLE',evidence='There are broad ~4-6 ppt SAP depressions at the Gaia-period screened phases in s25 (1986.44), s26 (2016.56) and s52 (2739.37), including two consecutive sector occasions and a 24-cycle longer separation. They do not show secure ingress/flat core/egress of a detached eclipse. The s52 phase trough is one of several smooth oscillatory troughs across that sector (approximately 2724, 2729, 2734 and 2739), so it does not isolate an orbit. At the same predicted phase, s40 is a positive ~2.5 ppt hump, s79 a sloping positive baseline, and s80 a sloping ~1 ppt deficit. Thus the broad resemblance is suggestive but not a measured same-kind ephemeris.',alternative='Terra independently extracted active-sky-corrected target-containing 3x3 apertures from valid 9x9 TESSCut cubes: the Gaia-phase +/-0.8 d cores versus 2-4 d sides show 4.38, 4.60 and 7.69 ppt deficits in s25, s26 and s52. QLP SAP gives 2.14, 5.37 and 7.91 ppt in those same windows. All three cutouts have positive target flux and no zero pixels. This supports a real aperture variation, but the same photons and a blended 3x3 extraction do not prove a target eclipse. KSPSAP strongly suppresses all three broad troughs, as expected for either long astrophysical events or raw extraction trends; suppression alone is not artifact proof.',geometry='Gaia P=30.11715 d; the s26 screening time is 3.74 d from the nearest edge-on conjunction against a 1.37 d linear allowance. The conditional phase coherence of broad troughs is not a measured photometric period.',limitations='Aperture variation is supported; eclipse morphology, timing centers and source attribution are insecure. Broad sector trends can mimic phase agreement.',next='Locate s25/s26/s52 deficits with convincing target-versus-background difference pixels and obtain a clean, bracketed repeat.'),
'T070':dict(verdict='PLAUSIBLE',evidence='The s6 1471.28 window contains a small ~1.5 ppt raw notch, with a 0.83 d gap shortly afterward. s32 at the Gaia-period phase is flat while s98 has a slow downward drift of about 1 ppt rather than a matching isolated dip. The newly available s107 has large positive pixel-flux excursions and no event-phase prediction in its time span. s108 covers the projected 4308.04 phase, but its WCS target pixel median is only ~0.15 counts and its extracted sums are noise dominated; it is not a sensitive null.',alternative='KSPSAP removes the s6 shallow notch, but a detrending response alone cannot refute a small eclipse. The s107 valid target-containing extraction shows unrelated large brightenings; the s108 near-zero target flux invalidates a lowest-pixel background or target-aperture null.',geometry='Gaia P=55.62273 d and the s6 screen is 0.27 d from predicted conjunction within 1.33 d linear allowance. Only one insecure event remains; no eclipse-based period is measured.',limitations='The original notch is shallow and only partially bracketed, with no established same-kind recurrence; s108 extraction cannot test the predicted phase.',next='Obtain target-flux-valid photometry at a future conjunction and difference pixels for a securely bracketed dip.'),
}

result=[]
for r in Q:
    sid=r['sample_id'];tic=r['tic'];d=I[sid];m=json.loads((B/tic/'lead-numeric.json').read_text());ff=F[sid]
    lines=[f'# {sid} / TIC {tic} - {d["verdict"]}', '',
        f'Queue stratum: {r["sample_stratum"]}. Gaia source {r["gaia_dr3"]}; selection P={float(r["gaia_period_days"]):.6f} d. Physical verdict and novelty are separate; shared catalogue status is UNKNOWN because four VizieR gates remain unavailable.', '',
        '## Raw evidence', '',d['evidence'],'',
        'The original detector windows are predictions, not eclipse centers. The exploratory local trapezoid fits in `lead-numeric.json` do not define an orbital ephemeris. Representative raw plots are `lead-raw-01.png`; full-sector SAP/KSPSAP context is in the `lead-sector-*.png` plots. `lead-fold-coverage.json` records time-bin core coverage and local contrast for returns conditional on the Gaia period point estimate. Period uncertainty accumulates over cycles; these phase checks are not calibrated nulls across the whole timing allowance. A flagged or gapped window is not a clean null.', '',
        '## Alternative reduction and attribution', '',d['alternative'],'',
        '## Orbital geometry', '',d['geometry'],'',
        '## Limits and next check', '',d['limitations'],'',d['next'],'',
        'Source receipts: the batch `SOURCE-HASHES.json` includes this TIC source packet, original bulk-window JSON and every used QLP FITS SHA-256. The shared Gaia neighbor and NSS catalogues and current TESSCut sector response are recorded once for the batch. New-sector TESSCut receipts, if present, are in this TIC directory.','']
    if sid in ('T061','T069'):
        lines.extend(['Independent helper pixel audit: `helper-audit.txt`, its `helper-*-numeric.json`/`helper-pixel-numeric.json` measurements, image plots, retrieval receipts and reproducible helper scripts in the batch folder.',''])
    report=B/tic/'REPORT.md';report.write_text('\n'.join(lines),encoding='utf-8')
    result.append(dict(sample_id=sid,tic=tic,sample_stratum=r['sample_stratum'],physical_verdict=d['verdict'],full_review_completion='COMPLETE',novelty_status='UNKNOWN',period_days='',period_error_days='',primary_epoch_btjd='',depth_ppt='',limitations=d['limitations'],next_check=d['next'],report=str(report)))
fields='sample_id,tic,sample_stratum,physical_verdict,full_review_completion,novelty_status,period_days,period_error_days,primary_epoch_btjd,depth_ppt,limitations,next_check,report'.split(',')
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(result)
print('wrote',len(result),'reports and result rows')
